# Simulación simple de transición de fase basada en métricas
def next_phase(active_users, growth_rate):
    if active_users < 1000:
        return "Discovery"
    elif growth_rate > 0.20:
        return "Growth"
    else:
        return "Maturity"

print(next_phase(active_users=1500, growth_rate=0.25))  # → Growth
```
